function turnpage(type, func) {
	var PageCount = $("#PageCount").html();
	var CurrIndex = $("#CurrIndex").html();
	var num = $("#CP").val();
	if (type == "PageFirst") {// 首页
		eval(func + "(1)");
	} else if (type == "pagePrevious") {// 上一页
		if (CurrIndex == '1') {
			alert("当前为首页。");
			return false;
		} else if (CurrIndex == '0') {
			alert("当前为首页。");
			return false;
		} else {
			num = CurrIndex * 1 - 1;
			eval(func + "(" + num * 1 + ")");
		}
	} else if (type == "pageNext") {// 下一页
		if (CurrIndex == PageCount) {
			alert("当前为尾页。");
			return false;
		} else {
			num = CurrIndex * 1 + 1;
			eval(func + "(" + num * 1 + ")");
		}
	} else if (type == "pageLast") {// 尾页
		eval(func + "(" + PageCount * 1 + ")");
	} else if (type == "pageNum") {// 跳转
		if (!(IsAllNumeric(num))) {
			alert("请填写数字。");
			return false;
		} else {
			if (PageCount * 1 < num * 1 || num * 1 == 0) {
				alert("请填写正确数字。");
				return false;
			} else {
				eval(func + "(" + num * 1 + ")");
			}
		}
	}
}
